def largestSquareOfOnes(matrix):
    n = len(matrix[0])
    prev = [0] * (n + 1)
    best = 0
    for row in matrix:
        cur = [0] * (n + 1)
        for c in range(n):
            if row[c] == 1:
                cur[c + 1] = 1 + min(prev[c], prev[c + 1], cur[c])
                if cur[c + 1] > best:
                    best = cur[c + 1]
        prev = cur
    return best * best
